package com.clavis.reader;
import android.app.*;import android.content.*;import android.net.Uri;import android.provider.DocumentsContract;import android.database.Cursor;import java.io.*;import java.util.*;
final class SharedDownloads {
 static Uri folder(Context c){String value=c.getSharedPreferences("download_settings",0).getString("folder","");return value.isEmpty()?null:Uri.parse(value);}
 static void open(MainActivity a){Uri target=folder(a);if(target==null){new AppDialog.Builder(a).setTitle("Clavis files").setMessage("Choose Clavis once to open and save books in that folder.").setPositiveButton("Choose folder",(d,n)->choose(a)).setNegativeButton("Cancel",null).show();return;}Intent view=new Intent(Intent.ACTION_VIEW).setDataAndType(target,DocumentsContract.Document.MIME_TYPE_DIR).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);try{a.startActivity(view);}catch(ActivityNotFoundException e){Intent picker=new Intent(Intent.ACTION_OPEN_DOCUMENT);picker.addCategory(Intent.CATEGORY_OPENABLE);picker.setType("*/*");picker.putExtra(DocumentsContract.EXTRA_INITIAL_URI,target);a.startActivityForResult(picker,23);}}
 static void openDownload(MainActivity a,TorrentJob job){Uri root=folder(a);if(root==null){open(a);return;}String safe=job.name.replaceAll("[\\/:]","_");if(safe.length()>120)safe=safe.substring(0,120);Uri target=DocumentsContract.buildDocumentUriUsingTree(root,DocumentsContract.getDocumentId(root)+"/"+safe);try(Cursor cursor=a.getContentResolver().query(target,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID},null,null,null)){if(cursor==null||!cursor.moveToFirst()){open(a);return;}}catch(Exception e){open(a);return;}Intent view=new Intent(Intent.ACTION_VIEW).setDataAndType(target,DocumentsContract.Document.MIME_TYPE_DIR).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);try{a.startActivity(view);}catch(ActivityNotFoundException e){Intent picker=new Intent(Intent.ACTION_OPEN_DOCUMENT);picker.addCategory(Intent.CATEGORY_OPENABLE);picker.setType("*/*");picker.putExtra(DocumentsContract.EXTRA_INITIAL_URI,target);a.startActivityForResult(picker,23);}}
 static void choose(MainActivity a){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);i.putExtra(DocumentsContract.EXTRA_INITIAL_URI,Uri.parse("content://com.android.externalstorage.documents/document/primary%3AClavis"));a.startActivityForResult(i,22);}
 static void accept(MainActivity a,Intent data){try{Uri tree=data.getData();if(tree==null)return;String id=DocumentsContract.getTreeDocumentId(tree);if(!id.equals("primary:Clavis"))throw new IOException("Choose the Clavis folder directly on internal storage.");a.getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);Uri target=DocumentsContract.buildDocumentUriUsingTree(tree,id);a.getSharedPreferences("download_settings",0).edit().putString("folder",target.toString()).apply();TorrentService.command(a,"publishall","");new AppDialog.Builder(a).setTitle("Download folder").setMessage("Completed books will be saved in Internal storage/Clavis.").setPositiveButton("OK",null).show();}catch(Exception e){new AppDialog.Builder(a).setTitle("Download folder").setMessage(e.getMessage()).setPositiveButton("Choose folder",(d,n)->choose(a)).setNegativeButton("Cancel",null).show();}}
 private static Uri directory(Context c,Uri parent,String name)throws IOException{Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(parent,DocumentsContract.getDocumentId(parent));try(Cursor cur=c.getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE},null,null,null)){if(cur!=null)while(cur.moveToNext())if(name.equals(cur.getString(1))&&DocumentsContract.Document.MIME_TYPE_DIR.equals(cur.getString(2)))return DocumentsContract.buildDocumentUriUsingTree(parent,cur.getString(0));}Uri created=DocumentsContract.createDocument(c.getContentResolver(),parent,DocumentsContract.Document.MIME_TYPE_DIR,name);if(created==null)throw new IOException("Cannot create Clavis folder");return created;}
 static Uri copyFile(Context c,File file,Uri parent)throws IOException{String lower=file.getName().toLowerCase(java.util.Locale.ROOT),mime=lower.endsWith(".pdf")?"application/pdf":lower.endsWith(".epub")?"application/epub+zip":"application/octet-stream";Uri out=DocumentsContract.createDocument(c.getContentResolver(),parent,mime,file.getName());if(out==null)throw new IOException("Cannot create shared download");try(InputStream in=new FileInputStream(file);OutputStream dest=c.getContentResolver().openOutputStream(out,"w")){if(dest==null)throw new IOException("Cannot write shared download");byte[] buf=new byte[131072];int n;while((n=in.read(buf))!=-1)dest.write(buf,0,n);}catch(IOException e){try{DocumentsContract.deleteDocument(c.getContentResolver(),out);}catch(Exception ignored){}throw e;}return out;}
 static void clearTemporary(File root){try{clearWithin(root,root.getCanonicalPath()+File.separator,true);}catch(IOException ignored){}}
 private static void clearWithin(File file,String root,boolean top)throws IOException{if(!top&&!file.getCanonicalPath().startsWith(root))return;if(file.isDirectory()){File[] children=file.listFiles();if(children!=null)for(File child:children)clearWithin(child,root,false);}file.delete();}
 static ArrayList<Book> publishTorrent(Context c,File source,String name)throws Exception{Uri root=folder(c);if(root==null)throw new IOException("Choose Clavis in Download settings to save the completed book");String safe=name.replaceAll("[\\/:]","_");if(safe.length()>120)safe=safe.substring(0,120);Uri target=directory(c,root,safe);copyFolder(c,source,target,source.getCanonicalPath()+File.separator,0);return FolderImporter.scanAt(c.getContentResolver(),target,DocumentsContract.getDocumentId(target));}
 private static void copyFolder(Context c,File dir,Uri target,String root,int depth)throws IOException{if(depth>40)throw new IOException("Folder nesting too deep");File[] files=dir.listFiles();if(files==null)throw new IOException("Temporary download is unreadable");for(File f:files){if(!f.getCanonicalPath().startsWith(root))continue;if(f.isDirectory())copyFolder(c,f,directory(c,target,f.getName()),root,depth+1);else if(!f.getName().startsWith("."))copyFile(c,f,target);}}
}
